using BC.FixedAsset.Core.Models;using BC.FixedAsset.Services;using System;using System.Globalization;using System.Linq;using System.Web.UI.WebControls;
namespace BC.FixedAsset.Web.FixedAsset.Survey{public partial class SurveyEdit:SecurePage{
protected HiddenField hidSurveyId;protected Label lblMessage;protected Button btnSave,btnSubmit;protected FileUpload fileActual,fileSerial,fileOther;protected Image imgActual,imgSerial,imgOther;protected TextBox txtAssetName,txtSurveyDate,txtBrand,txtModel,txtSerial,txtQuantity,txtWidth,txtLength,txtHeight,txtWeight,txtDimensionReason,txtReceivedDate,txtPo,txtEstimatedValue,txtRemark;protected DropDownList ddlDepartment,ddlCategory,ddlCustodian,ddlOwnership,ddlCondition,ddlUom,ddlBuilding,ddlFloor,ddlRoom;private readonly AssetSurveyService service=new AssetSurveyService();
protected void Page_Load(object s,EventArgs e){if(IsPostBack)return;Bind(ddlDepartment,"Department");Bind(ddlCategory,"Category");Bind(ddlCustodian,"User");Bind(ddlCondition,"Condition");Bind(ddlUom,"Uom");Bind(ddlBuilding,"Building");Bind(ddlFloor,"Floor");Bind(ddlRoom,"Room");hidSurveyId.Value=Request.QueryString["id"]??"0";txtSurveyDate.Text=DateTime.Today.ToString("yyyy-MM-dd");long id;if(long.TryParse(hidSurveyId.Value,out id)&&id>0)LoadSurvey(id);}
private void Bind(DropDownList list,string type){list.DataSource=service.GetReference(type);list.DataTextField="Name";list.DataValueField="Id";list.DataBind();}
private void LoadSurvey(long id){var x=service.Get(id,AssetAccess);if(x==null)throw new InvalidOperationException("ไม่พบข้อมูลหรือไม่มีสิทธิ์");Set(ddlDepartment,x.DepartmentId);Set(ddlCategory,x.CategoryId);if(x.CustodianUserId>0)Set(ddlCustodian,x.CustodianUserId);Set(ddlCondition,x.ConditionId);Set(ddlUom,x.UomId);Set(ddlBuilding,x.BuildingId);Set(ddlFloor,x.FloorId);Set(ddlRoom,x.RoomId);Set(ddlOwnership,x.OwnershipType);txtAssetName.Text=x.AssetName;txtSurveyDate.Text=x.SurveyDate.ToString("yyyy-MM-dd");txtBrand.Text=x.Brand;txtModel.Text=x.ModelDescription;txtSerial.Text=x.SerialNumber;txtQuantity.Text=x.Quantity.ToString(CultureInfo.InvariantCulture);txtWidth.Text=F(x.WidthCm);txtLength.Text=F(x.LengthCm);txtHeight.Text=F(x.HeightCm);txtWeight.Text=F(x.WeightKg);txtReceivedDate.Text=x.ReceivedDate.HasValue?x.ReceivedDate.Value.ToString("yyyy-MM-dd"):"";txtPo.Text=x.PurchaseOrderNo;txtEstimatedValue.Text=F(x.EstimatedValue);txtDimensionReason.Text=x.MissingDimensionReason;txtRemark.Text=x.Remark;foreach(var a in service.Attachments(id,AssetAccess)){var url=ResolveUrl("~/Attachment.ashx?id="+a.AttachmentId);if(a.AttachmentType=="ACTUAL")imgActual.ImageUrl=url;if(a.AttachmentType=="SERIAL")imgSerial.ImageUrl=url;if(a.AttachmentType=="OTHER")imgOther.ImageUrl=url;}var editable=x.Status==SurveyStatus.Draft||x.Status==SurveyStatus.Returned;btnSave.Visible=btnSubmit.Visible=editable;if(!string.IsNullOrWhiteSpace(x.ReturnReason))lblMessage.Text="Returned: "+Server.HtmlEncode(x.ReturnReason);}
protected void Save_Click(object s,EventArgs e){Save(false);}protected void Submit_Click(object s,EventArgs e){Save(true);}private void Save(bool submit){try{var survey=Form();var id=service.SaveDraft(survey,AssetAccess);hidSurveyId.Value=id.ToString();var root=Server.MapPath(System.Configuration.ConfigurationManager.AppSettings["UploadRoot"]);service.SaveAttachment(id,"ACTUAL",fileActual.PostedFile,AssetAccess,root);service.SaveAttachment(id,"SERIAL",fileSerial.PostedFile,AssetAccess,root);service.SaveAttachment(id,"OTHER",fileOther.PostedFile,AssetAccess,root);if(submit){service.Submit(id,AssetAccess);Response.Redirect("List.aspx",true);}lblMessage.Text="บันทึก Draft เรียบร้อย";LoadSurvey(id);}catch(Exception ex){lblMessage.Text=Server.HtmlEncode(ex.Message);}}
private AssetSurvey Form(){if(string.IsNullOrWhiteSpace(txtAssetName.Text))throw new ArgumentException("กรุณาระบุชื่อทรัพย์สิน");return new AssetSurvey{SurveyId=Convert.ToInt64(hidSurveyId.Value),SurveyDate=Date(txtSurveyDate.Text)??DateTime.Today,SurveyorUserId=CurrentUser.Id,DepartmentId=Convert.ToInt32(ddlDepartment.SelectedValue),CustodianUserId=Convert.ToInt32(ddlCustodian.SelectedValue),AssetName=txtAssetName.Text.Trim(),CategoryId=Convert.ToInt32(ddlCategory.SelectedValue),Brand=txtBrand.Text.Trim(),ModelDescription=txtModel.Text.Trim(),SerialNumber=txtSerial.Text.Trim(),OwnershipType=ddlOwnership.SelectedValue,ConditionId=Convert.ToInt32(ddlCondition.SelectedValue),WidthCm=D(txtWidth.Text),LengthCm=D(txtLength.Text),HeightCm=D(txtHeight.Text),WeightKg=D(txtWeight.Text),Quantity=decimal.Parse(txtQuantity.Text,CultureInfo.InvariantCulture),UomId=Convert.ToInt32(ddlUom.SelectedValue),BuildingId=Convert.ToInt32(ddlBuilding.SelectedValue),FloorId=Convert.ToInt32(ddlFloor.SelectedValue),RoomId=Convert.ToInt32(ddlRoom.SelectedValue),ReceivedDate=Date(txtReceivedDate.Text),PurchaseOrderNo=txtPo.Text.Trim(),EstimatedValue=D(txtEstimatedValue.Text),MissingDimensionReason=txtDimensionReason.Text.Trim(),Remark=txtRemark.Text.Trim()};}
private static void Set(ListControl x,object v){var item=x.Items.FindByValue(Convert.ToString(v));if(item!=null)x.SelectedValue=item.Value;}private static string F(decimal? v)=>v.HasValue?v.Value.ToString(CultureInfo.InvariantCulture):"";private static decimal? D(string v){decimal x;return decimal.TryParse(v,NumberStyles.Any,CultureInfo.InvariantCulture,out x)?x:(decimal?)null;}private static DateTime? Date(string v){DateTime x;return DateTime.TryParse(v,out x)?x:(DateTime?)null;}}}
